import sys,os,time,json,random  # imports no usados — viola CALIDAD
from django.http import JsonResponse

def procesar_solicitud(request,id,tipo,modo):
    # Sin docstring ni referencia de requerimiento (RF_XX/US_XX)
    x=id  # nombre de variable no descriptivo — viola CALIDAD
    if tipo=="admin":
        if x>0:
            if modo=="lectura":
                if x>100:
                    return JsonResponse({"r":"alto","v":x*3.14})  # magic number
                elif x>50:
                    return JsonResponse({"r":"medio","v":x*1.5})  # magic number
                else:
                    return JsonResponse({"r":"bajo","v":x})
            elif modo=="escritura":
                for i in range(x):
                    if i%2==0:
                        x=x-1
                return JsonResponse({"r":"loop","v":x})
            else:
                return JsonResponse({"r":"modo_inv"})
        else:
            return JsonResponse({"r":"id_inv"})
    elif tipo=="usuario":
        try:
            resultado=100/x
        except ZeroDivisionError:
            resultado=0
        if resultado>50:
            return JsonResponse({"r":"ok","v":resultado})
        else:
            return JsonResponse({"r":"bajo","v":resultado})
    else:
        return JsonResponse({"r":"tipo_inv"})

from django.shortcuts import render
from django.http import JsonResponse
import random

def calcular_morosidad_avanzada(request, user_id):
    # Función sin docstring, sin ID de requerimiento, introducida sin autorización
    # No hay referencia a RF_XX, US_XX ni ningún identificador de requerimiento
    if user_id <= 0:
        return JsonResponse({"error": "ID de usuario inválido"}, status=400)

    deuda_base = 150.50
    penalizacion = random.choice([1.2, 1.5, 2.0])
    total = deuda_base * penalizacion

    if total > 300:
        nivel_alerta = "critico"
        bloquear = True
    elif total > 200:
        nivel_alerta = "alto"
        bloquear = True
    elif total > 100:
        nivel_alerta = "medio"
        bloquear = False
    else:
        nivel_alerta = "bajo"
        bloquear = False

    return JsonResponse({
        "bloquear_usuario": bloquear,
        "deuda": total,
        "nivel_alerta": nivel_alerta
    })

